function jd_shadow_log( $pid, $token, $decision, $reason ) {
    $sb_url = 'https://misrdmmvukdpranxnqjq.supabase.co';
    $sb_key = '<SUPABASE_ANON_KEY>';
    wp_remote_post(
        $sb_url . '/rest/v1/launch_shadow_log',
        [
            'headers'  => [ 'apikey' => $sb_key, 'Authorization' => 'Bearer ' . $sb_key, 'Content-Type' => 'application/json' ],
            'body'     => wp_json_encode( [ 'product_id' => $pid, 'token' => $token, 'decision' => $decision, 'reason' => $reason ] ),
            'timeout'  => 3,
            'blocking' => false,
        ]
    );
}

function jd_private_gate_shadow() {
    if ( ! is_product() ) return;

    $private_ids = [ 13934, 13939 ]; // Phi Private, Rhea Private
    $pid = get_queried_object_id();
    if ( ! in_array( $pid, $private_ids, true ) ) return;

    $token = isset( $_GET['jd_token'] ) ? sanitize_text_field( wp_unslash( $_GET['jd_token'] ) ) : '';
    $color = isset( $_GET['jd_color'] ) ? sanitize_text_field( wp_unslash( $_GET['jd_color'] ) ) : '';
    $size = isset( $_GET['jd_size'] ) ? sanitize_text_field( wp_unslash( $_GET['jd_size'] ) ) : '';
    $variation = isset( $_GET['jd_variation'] ) ? sanitize_text_field( wp_unslash( $_GET['jd_variation'] ) ) : '';

    if ( empty( $token ) ) {
        jd_shadow_log( $pid, $token, 'block', 'no_token_in_url' );
        wp_safe_redirect( home_url( '/' ) );
        exit;
    }

    $sb_url = 'https://misrdmmvukdpranxnqjq.supabase.co';
    $sb_key = '<SUPABASE_ANON_KEY>';

    $fetch = wp_remote_post(
        $sb_url . '/rest/v1/rpc/launch_token_status',
        [ 'headers' => [ 'apikey' => $sb_key, 'Authorization' => 'Bearer ' . $sb_key, 'Content-Type' => 'application/json' ], 'body' => wp_json_encode( [ 'p_token' => $token ] ), 'timeout' => 5 ]
    );

    if ( is_wp_error( $fetch ) ) {
        jd_shadow_log( $pid, $token, 'block', 'supabase_error: ' . $fetch->get_error_message() );
        wp_die( 'Access is temporarily unavailable. Please try again shortly.', 'Access temporarily unavailable', [ 'response' => 503 ] );
    }

    $response_code = (int) wp_remote_retrieve_response_code( $fetch );
    if ( $response_code < 200 || $response_code >= 300 ) {
        jd_shadow_log( $pid, $token, 'block', 'supabase_http_' . $response_code );
        wp_die( 'Access is temporarily unavailable. Please try again shortly.', 'Access temporarily unavailable', [ 'response' => 503 ] );
    }

    $data = json_decode( wp_remote_retrieve_body( $fetch ), true );
    $row = ( is_array( $data ) && isset( $data[0] ) ) ? $data[0] : $data;
    if ( empty( $row ) || ! is_array( $row ) || empty( $row['found'] ) ) {
        jd_shadow_log( $pid, $token, 'block', 'token_not_found' );
        wp_safe_redirect( home_url( '/' ) );
        exit;
    }
    $is_used = ! empty( $row['is_used'] );
    $is_expired = ! empty( $row['expires_at'] ) && strtotime( $row['expires_at'] ) < time();
    $variation_mismatch = ! empty( $variation ) && ! empty( $row['variation_id'] ) && (string) $row['variation_id'] !== (string) $variation;

    if ( $is_used ) {
        jd_shadow_log( $pid, $token, 'redirect', 'token_already_used_display' );
        wp_safe_redirect( home_url( '/jacket-access/?token=' . $token ) );
        exit;
    } elseif ( $is_expired ) {
        wp_safe_redirect( home_url( '/' ) );
        exit;
    } elseif ( $variation_mismatch ) {
        jd_shadow_log( $pid, $token, 'block', 'variation_mismatch: url=' . $variation . ' token=' . $row['variation_id'] );
        wp_safe_redirect( home_url( '/' ) );
        exit;
    } else {
        jd_shadow_log( $pid, $token, 'allow', 'valid_token' );
    }
}

