  function scheduleFixInnerLayout(panel){
    if (pendingFix) return;
    pendingFix = true;
    requestAnimationFrame(function(){
      pendingFix = false;
      fixInnerLayout(panel);
    });
  }
  function watchPanel(panel){
    if (mo) mo.disconnect();
    mo = new MutationObserver(function(){ scheduleFixInnerLayout(panel); });
    mo.observe(panel, { childList: true, subtree: true });
  }
  function moveToBody(panel){
    if (panel.parentNode === document.body) return;
    placeholder = document.createComment('jd-cart-placeholder');
    panel.parentNode.insertBefore(placeholder, panel);
    document.body.appendChild(panel);
  }
  function restorePosition(panel){
    if (placeholder && placeholder.parentNode) {
      placeholder.parentNode.insertBefore(panel, placeholder);
      placeholder.parentNode.removeChild(placeholder);
      placeholder = null;
    }
  }
  var BASE_PANEL_CSS = 'display:flex !important;flex-direction:column !important;position:fixed !important;top:0 !important;right:0 !important;left:auto !important;height:100% !important;width:420px !important;max-width:92vw !important;z-index:' + Z_TOP + ' !important;overflow-y:auto !important;overflow-x:hidden !important;box-shadow:-2px 0 16px rgba(0,0,0,.12) !important;background:#fff !important;padding-top:56px !important;opacity:1 !important;visibility:visible !important;box-sizing:border-box !important;';
  function openDrawer(){
    var panel = document.querySelector(PANEL);
    if (!panel) return;
    if (panel.classList.contains('jd-force-open')) return;
    moveToBody(panel);
    fixInnerLayout(panel);
    watchPanel(panel);
    if (!panel.dataset.jdSavedStyle) panel.dataset.jdSavedStyle = panel.getAttribute('style') || '';
    panel.style.cssText = BASE_PANEL_CSS + 'transform:translateX(100%) !important;transition:none !important;';
    panel.classList.add('jd-force-open');
    var cc = ensureClickCatcher();
    cc.style.display = 'block';
    getComputedStyle(panel).transform;
    function startAnim(){
      panel.style.cssText = BASE_PANEL_CSS + 'transform:translateX(0) !important;transition:transform .6s ease !important;';
    }
    requestAnimationFrame(function(){ requestAnimationFrame(startAnim); });
    setTimeout(startAnim, 60);
  }
  function closeDrawer(){
    var panel = document.querySelector(PANEL);
    var cc = document.getElementById(CLICKCATCH_ID);
    if (mo) { mo.disconnect(); mo = null; }
    if (panel) {
      panel.style.cssText = BASE_PANEL_CSS + 'transform:translateX(100%) !important;transition:transform .6s ease !important;';
    }
    if (cc) { cc.style.display = 'none'; }
    setTimeout(function(){
      if (panel) {
        panel.setAttribute('style', panel.dataset.jdSavedStyle || '');
        panel.classList.remove('jd-force-open');
        restorePosition(panel);
      }
    }, 650);
  }
  function getCartCount(){
    var badge = document.querySelector('.de-cart__badges');
    var n = badge ? parseInt(badge.textContent.trim(), 10) : 0;
