/**
 * Jedda -- Fix Theme JS Errors
 * Patches two bugs in the Upscale theme's bundled Foundation Framework JS
 * that throw uncaught exceptions on every page load:
 *  1. jQuery.fn.load(fn) shorthand for window 'load' event -- removed in
 *     jQuery 3.x / jquery-migrate 3.x, but still used by foundation.min.js.
 *  2. Foundation._plugins.equalizer is not registered in this theme's
 *     Foundation build, but df-commerce.js calls it unconditionally on
 *     the shop page, crashing shop.init() before it finishes.
 * Both errors abort script execution early, which is the likely cause of
 * product grid / hero slider staying stuck in their initial hidden state.
 * Attached as inline code on the 'jquery' handle so it runs immediately
 * after jQuery loads and before any theme script that depends on it.
 */
add_action('wp_enqueue_scripts', function () {
    if (!wp_script_is('jquery', 'registered') && !wp_script_is('jquery', 'enqueued')) {
        return;
    }
    $patch = "
(function(){
  if (!window.jQuery) return;
  var jq = window.jQuery;
  if (!jq.fn.load.__jdPatched) {
    var __origLoad = jq.fn.load;
    jq.fn.load = function(a){
      if (typeof a === 'function' && arguments.length === 1) {
        return jq(window).on('load', a);
      }
      return __origLoad.apply(this, arguments);
    };
    jq.fn.load.__jdPatched = true;
  }
  var tries = 0;
  (function ensureEqualizerStub(){
    if (window.Foundation) {
      window.Foundation._plugins = window.Foundation._plugins || {};
      if (typeof window.Foundation._plugins.equalizer !== 'function') {
        window.Foundation._plugins.equalizer = function(){};
        window.Foundation._plugins.equalizer.prototype = {};
      }
      return;
    }
    if (tries++ < 400) setTimeout(ensureEqualizerStub, 5);
  })();
})();
";
    wp_add_inline_script('jquery', $patch);
}, 5);

