function jd_waitlist_valid_token( $tok ) {
    return ! empty( $tok ) && is_string( $tok ) && preg_match( '/^[A-Za-z0-9]{8,24}$/', $tok );
}

function jd_waitlist_private_product_ids() {
    return [ 13934, 13937, 13939 ]; // Phi/Rhea private parent IDs observed on staging.
}

function jd_waitlist_private_parent_id_from_context( $product_id, $variation_id = 0 ) {
    $product_id   = (int) $product_id;
    $variation_id = (int) $variation_id;

    if ( in_array( $product_id, jd_waitlist_private_product_ids(), true ) ) {
        return $product_id;
    }

    if ( $variation_id ) {
        $variation = wc_get_product( $variation_id );
        if ( $variation && $variation->is_type( 'variation' ) ) {
            $parent_id = (int) $variation->get_parent_id();
            if ( in_array( $parent_id, jd_waitlist_private_product_ids(), true ) ) {
                return $parent_id;
            }
        }
    }

    $product = $product_id ? wc_get_product( $product_id ) : null;
    if ( $product && $product->is_type( 'variation' ) ) {
        $parent_id = (int) $product->get_parent_id();
        if ( in_array( $parent_id, jd_waitlist_private_product_ids(), true ) ) {
            return $parent_id;
        }
    }

    return 0;
}

function jd_waitlist_cart_item_is_private( $item ) {
    $product_id = isset( $item['product_id'] ) ? (int) $item['product_id'] : 0;
    $variation_id = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : 0;
    return (bool) jd_waitlist_private_parent_id_from_context( $product_id, $variation_id );
}

function jd_waitlist_cart_has_private_item() {
    if ( ! WC()->cart ) return false;
    foreach ( WC()->cart->get_cart() as $item ) {
        if ( jd_waitlist_cart_item_is_private( $item ) ) return true;
    }
    return false;
}

function jd_waitlist_order_has_private_item( $order ) {
    if ( ! $order ) return false;
    foreach ( $order->get_items() as $item ) {
        $product = $item->get_product();
        $product_id = $product ? (int) $product->get_parent_id() : 0;
        if ( ! $product_id ) {
            $product_id = (int) $item->get_product_id();
        }
        if ( in_array( $product_id, jd_waitlist_private_product_ids(), true ) ) return true;
    }
    return false;
}

function jd_waitlist_get_cart_token() {
    if ( WC()->cart ) {
        foreach ( WC()->cart->get_cart() as $item ) {
            if ( ! empty( $item['_jd_waitlist_token'] ) && jd_waitlist_valid_token( $item['_jd_waitlist_token'] ) ) {
                return sanitize_text_field( $item['_jd_waitlist_token'] );
            }
        }
    }
    if ( WC()->session ) {
        $session_tok = WC()->session->get( 'jd_waitlist_token' );
        if ( jd_waitlist_valid_token( $session_tok ) ) return sanitize_text_field( $session_tok );
    }
    return '';
}

function jd_waitlist_response_ok( $response, $ok_codes = [ 200, 204 ] ) {
    if ( is_wp_error( $response ) ) return false;
    return in_array( (int) wp_remote_retrieve_response_code( $response ), $ok_codes, true );
}

function jd_waitlist_private_access_notice( $reason = '' ) {
    if ( 'used' === $reason ) {
        return 'This private access link has already been used. Each invitation can only be used once.';
    }
    if ( 'mismatch' === $reason ) {
        return 'Your private access is limited to the exact item, color, and size selected in your invitation.';
    }
    if ( 'cart_locked' === $reason ) {
        return 'This invitation is reserved exclusively for your selected item and variation. Complete your order first, then continue shopping.';
    }
    return 'We could not verify your private access. Please return to your invitation link and try again.';
}

