function jd_waitlist_redirect_to_access_message( $tok ) {
    if ( ! jd_waitlist_valid_token( $tok ) || ! jd_waitlist_should_redirect_customer() ) return false;

    wp_safe_redirect( home_url( '/jacket-access/?token=' . rawurlencode( $tok ) ) );
    exit;
}

function jd_waitlist_fetch_token_row( $tok ) {
    if ( ! jd_waitlist_valid_token( $tok ) ) {
        return new WP_Error( 'jd_invalid_token', 'Invalid waitlist token.' );
    }

    $rpc_headers = jd_waitlist_sb_headers();
    $rpc_headers['Content-Type'] = 'application/json';
    $fetch = wp_remote_post(
        jd_waitlist_sb_url() . '/rest/v1/rpc/launch_token_status',
        [ 'headers' => $rpc_headers, 'timeout' => 10, 'body' => wp_json_encode( [ 'p_token' => $tok ] ) ]
    );

    if ( is_wp_error( $fetch ) ) {
        return $fetch;
    }
    if ( ! jd_waitlist_response_ok( $fetch, [ 200 ] ) ) {
        return new WP_Error( 'jd_supabase_http', 'Supabase returned HTTP ' . wp_remote_retrieve_response_code( $fetch ) . '.' );
    }

    $row = json_decode( wp_remote_retrieve_body( $fetch ), true );
    if ( empty( $row ) || ! is_array( $row ) || empty( $row['found'] ) ) {
        return new WP_Error( 'jd_token_not_found', 'Waitlist token was not found.' );
    }

    return $row;
}

function jd_waitlist_token_is_expired( $row ) {
    return ! empty( $row['expires_at'] ) && strtotime( $row['expires_at'] ) < time();
}

function jd_waitlist_variation_belongs_to_product( $variation_id, $product_id ) {
    $variation_id = (int) $variation_id;
    $product_id   = (int) $product_id;
    if ( ! $variation_id || ! $product_id ) return false;

    $variation = wc_get_product( $variation_id );
    if ( ! $variation || ! $variation->is_type( 'variation' ) ) return false;

    return (int) $variation->get_parent_id() === $product_id;
}

function jd_waitlist_token_allows_item( $row, $product_id, $variation_id, &$reason = '' ) {
    if ( ! empty( $row['is_used'] ) ) {
        $reason = 'used';
        return false;
    }
    if ( jd_waitlist_token_is_expired( $row ) ) {
        $reason = 'expired';
        return false;
    }

    $expected_variation_id = (int) ( $row['variation_id'] ?? 0 );
    $variation_id          = (int) $variation_id;

    if ( ! $expected_variation_id || ! $variation_id || $expected_variation_id !== $variation_id ) {
        $reason = 'mismatch';
        return false;
    }

    if ( ! jd_waitlist_variation_belongs_to_product( $variation_id, $product_id ) ) {
        $reason = 'mismatch';
        return false;
    }

    $reason = 'ok';
    return true;
}

function jd_waitlist_add_order_note_once( $order, $message, $meta_key ) {
    if ( ! $order || $order->get_meta( $meta_key ) ) return;
    $order->add_order_note( $message );
    $order->update_meta_data( $meta_key, true );
    $order->save();
}

// ── 2. AJAX: simpan token ke WC session ──────────────────────────
add_action( 'wp_ajax_jd_store_token',        'jd_handle_store_token' );
add_action( 'wp_ajax_nopriv_jd_store_token', 'jd_handle_store_token' );

function jd_handle_store_token() {
    if ( ! check_ajax_referer( 'jd_store_token', 'nonce', false ) ) {
        wp_send_json_error( [ 'code' => 'invalid_nonce' ], 403 );
    }

    if ( ! function_exists( 'WC' ) || ! WC()->session ) {
        wp_send_json_error( [ 'code' => 'wc_session_unavailable' ], 500 );
    }

    $tok = sanitize_text_field( wp_unslash( $_POST['token'] ?? '' ) );
    if ( ! jd_waitlist_valid_token( $tok ) ) {
        wp_send_json_error( [ 'code' => 'invalid_token' ], 400 );
    }

    $existing_tok = WC()->session->get( 'jd_waitlist_token' );
    if ( ! empty( $existing_tok ) && $existing_tok !== $tok && WC()->cart && ! WC()->cart->is_empty() ) {
        WC()->cart->empty_cart();
    }

    WC()->session->set( 'jd_waitlist_token', $tok );
    $stored_tok = WC()->session->get( 'jd_waitlist_token' );
    if ( $stored_tok !== $tok ) {
        wp_send_json_error( [ 'code' => 'session_write_failed' ], 500 );
    }

    wp_send_json_success( [ 'token_bound' => true ] );
}

// ── 3. Bawa token dari private product ke cart item ───────────────
add_filter( 'woocommerce_add_to_cart_validation', 'jd_validate_waitlist_add_to_cart', 5, 5 );
add_filter( 'woocommerce_add_cart_item_data', 'jd_add_waitlist_token_to_cart_item', 10, 3 );
add_action( 'woocommerce_add_to_cart', 'jd_scrub_waitlist_cart_after_add', 20, 6 );
add_action( 'template_redirect', 'jd_scrub_invalid_waitlist_cart_on_page_load', 8 );

function jd_validate_waitlist_add_to_cart( $passed, $product_id, $quantity, $variation_id = 0, $variations = [] ) {
    if ( ! $passed ) return false;

    $product_id          = (int) $product_id;
    $variation_id        = (int) $variation_id;
    $private_parent_id   = jd_waitlist_private_parent_id_from_context( $product_id, $variation_id );
    $incoming_is_private = (bool) $private_parent_id;

    if ( WC()->cart && jd_waitlist_cart_has_private_item() && ! $incoming_is_private ) {
        wc_add_notice( jd_waitlist_private_access_notice( 'cart_locked' ), 'error' );
        if ( jd_waitlist_should_redirect_customer() ) {
            wp_safe_redirect( add_query_arg( 'jd_cart_locked', '1', wc_get_cart_url() ) );
            exit;
        }
        return false;
    }

    if ( ! $incoming_is_private ) {
        return $passed;
    }

    $tok = sanitize_text_field( wp_unslash( $_REQUEST['jd_token'] ?? '' ) );
    if ( ! jd_waitlist_valid_token( $tok ) && WC()->session ) {
        $tok = WC()->session->get( 'jd_waitlist_token' );
    }

    if ( ! jd_waitlist_valid_token( $tok ) ) {
        wc_add_notice( jd_waitlist_private_access_notice(), 'error' );
        return false;
    }

    $row = jd_waitlist_fetch_token_row( $tok );
    if ( is_wp_error( $row ) ) {
        wc_add_notice( jd_waitlist_private_access_notice(), 'error' );
        return false;
    }

    $reason = '';
    if ( ! jd_waitlist_token_allows_item( $row, $private_parent_id, $variation_id, $reason ) ) {
        if ( 'used' === $reason ) {
            jd_waitlist_redirect_to_access_message( $tok );
        }
        wc_add_notice( jd_waitlist_private_access_notice( $reason ), 'error' );
        return false;
    }

    if ( WC()->cart && ! WC()->cart->is_empty() ) {
        foreach ( WC()->cart->get_cart() as $item ) {
            $item_variation_id = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : 0;
            if ( $item_variation_id !== $variation_id ) {
                wc_add_notice( jd_waitlist_private_access_notice( 'cart_locked' ), 'error' );
                return false;
            }
        }
    }

    return $passed;
}

function jd_scrub_waitlist_cart_after_add( $cart_item_key, $product_id, $quantity, $variation_id, $variation, $cart_item_data ) {
    if ( ! WC()->cart ) return;
    if ( empty( WC()->cart->cart_contents[ $cart_item_key ] ) ) return;

    $item              = WC()->cart->cart_contents[ $cart_item_key ];
    $product_id        = isset( $item['product_id'] ) ? (int) $item['product_id'] : (int) $product_id;
    $variation_id      = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : (int) $variation_id;
    $private_parent_id = jd_waitlist_private_parent_id_from_context( $product_id, $variation_id );

    if ( ! $private_parent_id && jd_waitlist_cart_has_private_item() ) {
        WC()->cart->remove_cart_item( $cart_item_key );
        wc_add_notice( jd_waitlist_private_access_notice( 'cart_locked' ), 'error' );
        return;
    }

    if ( ! $private_parent_id ) return;

    $tok = ! empty( $item['_jd_waitlist_token'] ) ? sanitize_text_field( $item['_jd_waitlist_token'] ) : '';
    if ( ! jd_waitlist_valid_token( $tok ) ) {
        $tok = sanitize_text_field( wp_unslash( $_REQUEST['jd_token'] ?? '' ) );
    }
    if ( ! jd_waitlist_valid_token( $tok ) && WC()->session ) {
        $tok = WC()->session->get( 'jd_waitlist_token' );
    }

    $reason = '';
    $row    = jd_waitlist_valid_token( $tok ) ? jd_waitlist_fetch_token_row( $tok ) : new WP_Error( 'jd_missing_token', 'Missing waitlist token.' );
    if ( is_wp_error( $row ) || ! jd_waitlist_token_allows_item( $row, $private_parent_id, $variation_id, $reason ) ) {
        WC()->cart->remove_cart_item( $cart_item_key );
        if ( 'used' === $reason ) {
            jd_waitlist_redirect_to_access_message( $tok );
        }
        wc_add_notice( jd_waitlist_private_access_notice( is_wp_error( $row ) ? '' : $reason ), 'error' );
    }
}

function jd_scrub_invalid_waitlist_cart_on_page_load() {
    if ( ! function_exists( 'WC' ) || ! WC()->cart ) return;
    if ( ! ( is_cart() || is_checkout() ) ) return;

    $cart = WC()->cart;
    if ( $cart->is_empty() ) return;

    $redirect_token = '';
    $removed_any    = false;

    foreach ( $cart->get_cart() as $cart_item_key => $item ) {
        if ( ! jd_waitlist_cart_item_is_private( $item ) ) continue;

        $product_id        = isset( $item['product_id'] ) ? (int) $item['product_id'] : 0;
        $variation_id      = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : 0;
        $private_parent_id = jd_waitlist_private_parent_id_from_context( $product_id, $variation_id );
        $tok               = ! empty( $item['_jd_waitlist_token'] ) ? sanitize_text_field( $item['_jd_waitlist_token'] ) : jd_waitlist_get_cart_token();
        $reason            = '';

        $row = jd_waitlist_valid_token( $tok ) ? jd_waitlist_fetch_token_row( $tok ) : new WP_Error( 'jd_missing_token', 'Missing waitlist token.' );
        if ( is_wp_error( $row ) || ! jd_waitlist_token_allows_item( $row, $private_parent_id, $variation_id, $reason ) ) {
            $cart->remove_cart_item( $cart_item_key );
            $removed_any = true;
            if ( 'used' === $reason && jd_waitlist_valid_token( $tok ) ) {
                $redirect_token = $tok;
            }
        }
    }

    if ( $removed_any ) {
        $cart->calculate_totals();
    }

    if ( $redirect_token ) {
        jd_waitlist_redirect_to_access_message( $redirect_token );
    }
}

function jd_add_waitlist_token_to_cart_item( $cart_item_data, $product_id, $variation_id ) {
    $tok = sanitize_text_field( wp_unslash( $_REQUEST['jd_token'] ?? '' ) );
    if ( ! jd_waitlist_valid_token( $tok ) ) return $cart_item_data;

    $cart_item_data['_jd_waitlist_token']     = $tok;
    $cart_item_data['_jd_waitlist_variation'] = absint( $_REQUEST['jd_variation'] ?? $variation_id );
    $cart_item_data['_jd_waitlist_color']     = sanitize_text_field( wp_unslash( $_REQUEST['jd_color'] ?? '' ) );
    $cart_item_data['_jd_waitlist_size']      = sanitize_text_field( wp_unslash( $_REQUEST['jd_size'] ?? '' ) );
    $cart_item_data['unique_key']             = md5( $tok . '|' . (string) $variation_id . '|' . microtime() );

    if ( WC()->session ) {
        WC()->session->set( 'jd_waitlist_token', $tok );
    }

    return $cart_item_data;
}

add_filter( 'woocommerce_get_cart_item_from_session', 'jd_restore_waitlist_token_cart_item', 10, 2 );

function jd_restore_waitlist_token_cart_item( $cart_item, $values ) {
    foreach ( [ '_jd_waitlist_token', '_jd_waitlist_variation', '_jd_waitlist_color', '_jd_waitlist_size' ] as $key ) {
        if ( isset( $values[ $key ] ) ) $cart_item[ $key ] = $values[ $key ];
    }
    return $cart_item;
}

add_action( 'woocommerce_checkout_create_order_line_item', 'jd_attach_waitlist_token_to_order_item', 10, 4 );

function jd_attach_waitlist_token_to_order_item( $item, $cart_item_key, $values, $order ) {
    if ( ! empty( $values['_jd_waitlist_token'] ) ) {
        $item->add_meta_data( '_jd_waitlist_token', sanitize_text_field( $values['_jd_waitlist_token'] ), true );
    }
    if ( ! empty( $values['_jd_waitlist_variation'] ) ) {
        $item->add_meta_data( '_jd_waitlist_variation', absint( $values['_jd_waitlist_variation'] ), true );
    }
}

// ── 4. Attach token ke WooCommerce order saat checkout ───────────
add_action( 'woocommerce_checkout_create_order', 'jd_attach_token_to_order', 10, 2 );

function jd_attach_token_to_order( $order, $data ) {
    $tok = jd_waitlist_get_cart_token();
    if ( ! empty( $tok ) ) {
        $order->update_meta_data( '_jd_waitlist_token', sanitize_text_field( $tok ) );
        $order->update_meta_data( '_jd_waitlist_token_source', 'cart_or_session' );
    }
}

add_action( 'woocommerce_after_checkout_validation', 'jd_validate_private_checkout_has_token', 10, 2 );

function jd_validate_private_checkout_has_token( $data, $errors ) {
    if ( ! jd_waitlist_cart_has_private_item() ) return;

    $tok = jd_waitlist_get_cart_token();
    if ( ! $tok ) {
        $errors->add( 'jd_waitlist_missing_token', 'We could not verify your private access. Please return to your invitation link and try again.' );
        return;
    }

    $row = jd_waitlist_fetch_token_row( $tok );
    if ( is_wp_error( $row ) ) {
        $errors->add( 'jd_waitlist_token_unavailable', jd_waitlist_private_access_notice() );
        return;
    }

    $items = WC()->cart ? WC()->cart->get_cart() : [];
    if ( count( $items ) !== 1 ) {
        $errors->add( 'jd_waitlist_cart_locked', jd_waitlist_private_access_notice( 'cart_locked' ) );
        return;
    }

    foreach ( $items as $item ) {
        $reason = '';
        $item_product_id   = isset( $item['product_id'] ) ? (int) $item['product_id'] : 0;
        $item_variation_id = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : 0;
        if ( ! jd_waitlist_token_allows_item( $row, $item_product_id, $item_variation_id, $reason ) ) {
            $errors->add( 'jd_waitlist_item_mismatch', jd_waitlist_private_access_notice( $reason ) );
            return;
        }
    }
}

// ── 5. Payment confirmed → update Supabase ────────────────────────
add_action( 'woocommerce_payment_complete',        'jd_on_order_paid' );
add_action( 'woocommerce_order_status_processing', 'jd_on_order_paid' );
add_action( 'woocommerce_order_status_completed',  'jd_on_order_paid' );
add_action( 'jd_retry_order_paid_token',           'jd_on_order_paid' );

function jd_schedule_token_retry( $order, $reason ) {
    if ( ! $order ) return;
    $attempts = (int) $order->get_meta( '_jd_token_retry_attempts' );
    if ( $attempts >= 3 ) {
        jd_waitlist_add_order_note_once( $order, 'JEDDA waitlist token update failed after 3 retries. Please review this order manually.', '_jd_token_retry_escalated_note' );
        return;
    }

    $attempts++;
    $order->update_meta_data( '_jd_token_retry_attempts', $attempts );
    $order->update_meta_data( '_jd_token_retry_reason', sanitize_text_field( $reason ) );
    $order->save();

    $delays = [ 300, 900, 1800 ];
    $delay  = $delays[ max( 0, min( $attempts - 1, count( $delays ) - 1 ) ) ];

    if ( function_exists( 'as_next_scheduled_action' ) && function_exists( 'as_schedule_single_action' ) ) {
        $next = as_next_scheduled_action( 'jd_retry_order_paid_token', [ $order->get_id() ], 'jedda-waitlist' );
        if ( ! $next ) {
            as_schedule_single_action( time() + $delay, 'jd_retry_order_paid_token', [ $order->get_id() ], 'jedda-waitlist' );
        }
    } else {
        jd_waitlist_add_order_note_once( $order, 'JEDDA waitlist token update needs manual review. Retry scheduler is unavailable.', '_jd_token_retry_scheduler_missing_note' );
    }
}

function jd_on_order_paid( $order_id ) {
    $order = wc_get_order( $order_id );
    if ( ! $order ) return;
    if ( $order->get_meta( '_jd_token_processed' ) ) return;
    if ( ! jd_waitlist_order_has_private_item( $order ) ) return;

    $tok = $order->get_meta( '_jd_waitlist_token' );
    if ( ! jd_waitlist_valid_token( $tok ) ) {
        foreach ( $order->get_items() as $item ) {
            $item_tok = $item->get_meta( '_jd_waitlist_token' );
            if ( jd_waitlist_valid_token( $item_tok ) ) {
                $tok = sanitize_text_field( $item_tok );
                $order->update_meta_data( '_jd_waitlist_token', $tok );
                $order->update_meta_data( '_jd_waitlist_token_source', 'order_item_fallback' );
                break;
            }
        }
    }

    if ( ! jd_waitlist_valid_token( $tok ) ) {
        error_log( '[JD] No _jd_waitlist_token on order ' . $order_id );
        jd_waitlist_add_order_note_once( $order, 'JEDDA waitlist token missing. Private invitation was not marked used automatically.', '_jd_token_missing_note' );
        return;
    }

    $sb_url = jd_waitlist_sb_url();
    $hdrs   = jd_waitlist_sb_headers( true );

    $rpc_headers = jd_waitlist_sb_headers();
    $rpc_headers['Content-Type'] = 'application/json';
    $fetch = wp_remote_post(
        $sb_url . '/rest/v1/rpc/launch_token_status',
        [ 'headers' => $rpc_headers, 'timeout' => 10, 'body' => wp_json_encode( [ 'p_token' => $tok ] ) ]
    );
    if ( is_wp_error( $fetch ) ) {
        error_log( '[JD] SB GET error order ' . $order_id . ': ' . $fetch->get_error_message() );
        jd_schedule_token_retry( $order, 'supabase_get_error' );
        return;
    }
    if ( ! jd_waitlist_response_ok( $fetch, [ 200 ] ) ) {
        error_log( '[JD] SB GET HTTP ' . wp_remote_retrieve_response_code( $fetch ) . ' order ' . $order_id );
        jd_schedule_token_retry( $order, 'supabase_get_http_' . wp_remote_retrieve_response_code( $fetch ) );
        return;
    }

    $rows = json_decode( wp_remote_retrieve_body( $fetch ), true );
    if ( empty( $rows ) || empty( $rows['found'] ) ) {
        error_log( '[JD] Token not found in Supabase: ' . $tok );
        jd_waitlist_add_order_note_once( $order, 'JEDDA waitlist token was not found in Supabase. Please review this order manually.', '_jd_token_not_found_note' );
        return;
    }
    $waitlist_id = $rows['waitlist_id'] ?? null;

    $expected_variation_id = isset( $rows['variation_id'] ) ? (int) $rows['variation_id'] : 0;
    if ( $expected_variation_id ) {
        $matched = false;
        foreach ( $order->get_items() as $item ) {
            $item_variation_id = method_exists( $item, 'get_variation_id' ) ? (int) $item->get_variation_id() : 0;
            if ( $item_variation_id === $expected_variation_id ) {
                $matched = true;
                break;
            }
        }
        if ( ! $matched ) {
            error_log( '[JD] MISMATCH: order ' . $order_id . ' token ' . $tok . ' expected variation ' . $expected_variation_id . ' but order does not contain it. Token will still be marked used to prevent repeat abuse.' );
            $order->update_meta_data( '_jd_token_mismatch', true );
        }
    }

    // C2: consume token via SECURITY DEFINER RPC (marks used + sets waitlist purchased).
    // Needed because direct anon UPDATE-by-token no longer resolves once anon SELECT is closed.
    $consume = wp_remote_post(
        $sb_url . '/rest/v1/rpc/launch_consume_token',
        [ 'headers' => $rpc_headers, 'timeout' => 10, 'body' => wp_json_encode( [ 'p_token' => $tok, 'p_order_id' => (string) $order_id ] ) ]
    );

    if ( ! jd_waitlist_response_ok( $consume, [ 200 ] ) ) {
        $code = is_wp_error( $consume ) ? $consume->get_error_message() : wp_remote_retrieve_response_code( $consume );
        error_log( '[JD] SB consume_token failed order ' . $order_id . ': ' . $code );
        jd_schedule_token_retry( $order, 'launch_consume_failed' );
        return;
    }

    $consume_result = json_decode( wp_remote_retrieve_body( $consume ), true );
    if ( empty( $consume_result ) || empty( $consume_result['ok'] ) ) {
        error_log( '[JD] consume_token not ok order ' . $order_id . ': ' . wp_remote_retrieve_body( $consume ) );
        jd_schedule_token_retry( $order, 'launch_consume_not_ok' );
        return;
    }

    $order->update_meta_data( '_jd_token_processed', true );
    $order->delete_meta_data( '_jd_token_retry_reason' );
    $order->save();

    if ( WC()->session && WC()->session->get( 'jd_waitlist_token' ) === $tok ) {
        WC()->session->__unset( 'jd_waitlist_token' );
    }

    error_log( '[JD] Paid: order=' . $order_id . ' tok=' . $tok . ' wl=' . $waitlist_id );
}

// ── 6. Cegah cart mixing: token waitlist hanya boleh checkout dengan 1 item yang cocok ──
add_action( 'woocommerce_check_cart_items', 'jd_enforce_single_waitlist_item' );

function jd_enforce_single_waitlist_item() {
    if ( ! jd_waitlist_cart_has_private_item() ) return; // H6FIX: hanya enforce kalau keranjang berisi item private; cegah token session basi memblokir checkout produk biasa
    $tok = jd_waitlist_get_cart_token();
    if ( empty( $tok ) ) return;

    $cart = WC()->cart;
    if ( ! $cart || $cart->is_empty() ) return;

    $row = jd_waitlist_fetch_token_row( $tok );
    if ( is_wp_error( $row ) ) {
        wc_add_notice( jd_waitlist_private_access_notice(), 'error' );
        return;
    }
    if ( ! empty( $row['is_used'] ) || jd_waitlist_token_is_expired( $row ) ) {
        wc_add_notice( jd_waitlist_private_access_notice( ! empty( $row['is_used'] ) ? 'used' : 'expired' ), 'error' );
        return;
    }

    $expected_variation_id = (int) ( $row['variation_id'] ?? 0 );
    if ( ! $expected_variation_id ) {
        wc_add_notice( jd_waitlist_private_access_notice(), 'error' );
        return;
    }

    $items = $cart->get_cart();
    $has_mismatch = false;
    foreach ( $items as $item ) {
        $variation_id = isset( $item['variation_id'] ) ? (int) $item['variation_id'] : 0;
        $product_id   = isset( $item['product_id'] ) ? (int) $item['product_id'] : 0;
        if ( $variation_id !== $expected_variation_id || ! jd_waitlist_variation_belongs_to_product( $variation_id, $product_id ) ) {
            $has_mismatch = true;
        }
    }

    if ( count( $items ) > 1 || $has_mismatch ) {
        wc_add_notice( 'Your waitlist access is limited to the exact item you registered for. Please remove any other items from your cart before checking out.', 'error' );
    }
}

(function(){
