/* Jedda M7: rebuild bare private (hidden) rows in the cart drawer using the theme's
   own markup (.de-cart__list-item-inner > .de-cart__list-media + .de-cart__list-meta),
   so fonts, spacing, layout and mobile behaviour match regular items exactly.
   Qty is rendered as a static "1" on purpose: private items are locked to a single
   unit per token, so no +/- controls. Remove works via the WooCommerce Store API. */
(function(){
  var STORE = '/wp-json/wc/store/v1/cart';
  var nonce = null;

  function fmt(minor, unit, prefix){
    var n = parseInt(minor,10) || 0;
    if(unit > 0) n = n / Math.pow(10, unit);
    var s = Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    return (prefix || 'Rp ') + s;
  }

  function doRemove(key, el){
    el.textContent = 'Removing…';
    fetch(STORE + '/remove-item', {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json', 'Nonce': nonce || '' },
      body: JSON.stringify({ key: key })
    }).then(function(r){ if(!r.ok) throw new Error('remove failed'); location.reload(); })
      .catch(function(){ location.reload(); });
  }

  function enhance(){
    var rows = Array.prototype.slice.call(document.querySelectorAll('.de-cart__list-item.de-mini-cart'));
    var pending = rows.filter(function(r){
      if(r.getAttribute('data-jd-enh') === '1') return false;
      // A bare private row has only an <img> element child; regular rows carry the
      // theme's .de-cart__list-item-inner wrapper — leave those untouched.
      var extra = Array.prototype.filter.call(r.children, function(c){ return c.tagName !== 'IMG'; });
      if(extra.length) return false;
      return true;
    });
    if(!pending.length) return;
    fetch(STORE, { credentials: 'same-origin' }).then(function(r){
      nonce = r.headers.get('Nonce') || nonce;
      return r.json();
    }).then(function(data){
      var items = (data.items || []).slice();
      pending.forEach(function(row){
        if(row.getAttribute('data-jd-enh') === '1') return;
        var txt = (row.textContent || '').trim();
        var idx = -1;
        for(var i=0;i<items.length;i++){
          if(items[i] && items[i].name && txt.indexOf(items[i].name) === 0){ idx = i; break; }
        }
        if(idx < 0) return;
        var m = items[idx]; items.splice(idx, 1);
        row.setAttribute('data-jd-enh', '1');

        var img = row.querySelector('img');
        // rebuild with the theme's own structure
        var inner = document.createElement('div'); inner.className = 'de-cart__list-item-inner';
        var media = document.createElement('div'); media.className = 'de-cart__list-media';
        if(img) media.appendChild(img);
        var rm = document.createElement('a'); rm.className = 'remove'; rm.href = '#';
        rm.textContent = 'Remove';
        rm.addEventListener('click', function(e){ e.preventDefault(); e.stopPropagation(); doRemove(m.key, rm); });
        media.appendChild(rm);

        var meta = document.createElement('div'); meta.className = 'de-cart__list-meta';
        var h5 = document.createElement('h5');
        var nameA = document.createElement('a'); nameA.href = '/cart/'; nameA.textContent = txt;
        h5.appendChild(nameA);
        var qty = document.createElement('span'); qty.className = 'de-cart__list-item-qty';
        var q = document.createElement('span'); q.className = 'quantity'; q.textContent = '1';
        qty.appendChild(q);
        var price = document.createElement('span'); price.className = 'woocommerce-Price-amount amount';
        var bdi = document.createElement('bdi');
        bdi.textContent = fmt(m.prices.price, m.prices.currency_minor_unit, m.prices.currency_prefix);
        price.appendChild(bdi);
        meta.appendChild(h5); meta.appendChild(qty); meta.appendChild(price);

        inner.appendChild(media); inner.appendChild(meta);
        while(row.firstChild){ row.removeChild(row.firstChild); }
        row.appendChild(inner);
      });
    }).catch(function(){});
  }

  function boot(){
    enhance();
    if(window.jQuery){
      jQuery(document.body).on('wc_fragments_refreshed added_to_cart wc_fragments_loaded', function(){ enhance(); setTimeout(enhance, 60); setTimeout(enhance, 250); });
    document.addEventListener('click', function(e){
      if(e.target && e.target.closest && e.target.closest('.de-cart__logo, .de-cart > a, #jd-mobile-cart-menuitem, .jd-cart-close')){
        enhance(); setTimeout(enhance, 60); setTimeout(enhance, 250); setTimeout(enhance, 500);
      }
    }, true);
    }
    var drawer = document.querySelector('.de-cart');
    if(drawer){ try{ new MutationObserver(function(){ enhance(); }).observe(drawer, { childList: true, subtree: true }); }catch(e){} }
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
})();

// Live sync: every time an order reaches processing/completed, push its
// line items (email, phone, product, variation) to Supabase web_purchases.
// Fires once per order transition -- NOT a bulk historical scan.
add_action( "woocommerce_order_status_processing", "jd_sync_order_to_web_purchases" );
add_action( "woocommerce_order_status_completed",  "jd_sync_order_to_web_purchases" );

function jd_sync_order_to_web_purchases( $order_id ) {
    $order = wc_get_order( $order_id );
    if ( ! $order ) return;

    $sb_url = "https://misrdmmvukdpranxnqjq.supabase.co";
    $sb_key = "<SUPABASE_SERVICE_ROLE_KEY>" /* GANTI dengan service_role key dari Supabase Dashboard > Settings > API. JANGAN pakai anon key lagi: web_purchases sudah dikunci RLS, cuma service_role yang boleh nulis. Key ini kunci master -- hanya boleh hidup di PHP snippet, jangan pernah di HTML/JS. */;
    $hdrs = array(
        "apikey"        => $sb_key,
        "Authorization" => "Bearer " . $sb_key,
        "Content-Type"  => "application/json",
        "Prefer"        => "resolution=merge-duplicates,return=minimal",
    );

    $email  = $order->get_billing_email();
    $phone  = $order->get_billing_phone();
    $status = $order->get_status();
    $date   = $order->get_date_created() ? $order->get_date_created()->date( "c" ) : null;

    $rows = array();
    foreach ( $order->get_items() as $item ) {
        $rows[] = array(
            "order_id"     => (int) $order_id,
            "product_id"   => (int) $item->get_product_id(),
            "variation_id" => (int) $item->get_variation_id(),
            "product_name" => $item->get_name(),
            "email"        => $email,
            "phone"        => $phone,
            "order_status" => $status,
            "order_date"   => $date,
        );
    }
    if ( empty( $rows ) ) return;

    wp_remote_post(
        $sb_url . "/rest/v1/web_purchases?on_conflict=order_id,product_id,variation_id",
        array(
            "headers" => $hdrs,
            "body"    => wp_json_encode( $rows ),
            'blocking' => false,
            "timeout" => 15,
        )
    );
}

/*
JEDDA JASTIP LIVE DETECTOR
Hook ke WooCommerce order status (processing/completed/refunded).
Cuma proses order yang line item-nya match watched product (nama produk,
bukan SKU/kategori) — kirim ke Supabase RPC jastip_ingest_order() yang
jalanin rule engine (DB match, bulk-same-product, cross-order-same-product).
*/

if ( ! function_exists( 'jd_jastip_get_watched_keywords' ) ) {
  function jd_jastip_get_watched_keywords() {
    $cached = get_transient( 'jd_jastip_watched_keywords' );
    if ( $cached !== false ) {
      return $cached;
    }
    $url = 'https://misrdmmvukdpranxnqjq.supabase.co/rest/v1/jastip_watched_products?active=eq.true&select=keyword';
    $resp = wp_remote_get( $url, array(
      'headers' => array(
        'apikey'        => '<SUPABASE_ANON_KEY>',
        'Authorization' => 'Bearer <SUPABASE_ANON_KEY>',
      ),
      'timeout' => 8,
    ) );
    if ( is_wp_error( $resp ) ) {
      return array();
    }
    $body = json_decode( wp_remote_retrieve_body( $resp ), true );
    if ( ! is_array( $body ) ) {
      return array();
    }
    $keywords = array_map( function( $row ) {
      return strtolower( $row['keyword'] );
    }, $body );
    set_transient( 'jd_jastip_watched_keywords', $keywords, 5 * MINUTE_IN_SECONDS );
    return $keywords;
  }
}

if ( ! function_exists( 'jd_jastip_check_order' ) ) {
  function jd_jastip_check_order( $order_id ) {
    $order = wc_get_order( $order_id );
    if ( ! $order ) {
      return;
    }

    $keywords = jd_jastip_get_watched_keywords();
    if ( empty( $keywords ) ) {
      return;
    }

    $products = array();
    $has_watched = false;

    foreach ( $order->get_items() as $item ) {
      $name = $item->get_name();
      $qty  = $item->get_quantity();
      $products[] = array( 'name' => $name, 'qty' => (int) $qty );

      $name_lower = strtolower( $name );
      foreach ( $keywords as $kw ) {
        if ( strpos( $name_lower, $kw ) !== false ) {
          $has_watched = true;
          break;
        }
      }
    }

    // Skip order yang tidak menyangkut watched product sama sekali —
    // biar jastip_orders cuma isi order yang relevan, bukan semua 7000 order.
    if ( ! $has_watched ) {
      return;
    }

    $recipient_name = trim( $order->get_shipping_first_name() . ' ' . $order->get_shipping_last_name() );
    if ( $recipient_name === '' ) {
      $recipient_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );
    }

    $phone = method_exists( $order, 'get_shipping_phone' ) ? $order->get_shipping_phone() : '';
    if ( empty( $phone ) ) {
      $phone = $order->get_billing_phone();
  $email = $order->get_billing_email();
    }

    $address_raw = trim( $order->get_shipping_address_1() . ' ' . $order->get_shipping_address_2() );
    if ( $address_raw === '' ) {
      $address_raw = trim( $order->get_billing_address_1() . ' ' . $order->get_billing_address_2() );
    }

    $city     = $order->get_shipping_city() ?: $order->get_billing_city();
    $province = $order->get_shipping_state() ?: $order->get_billing_state();
    $postal   = $order->get_shipping_postcode() ?: $order->get_billing_postcode();

    $payload = array(
      'p_order_no'       => (string) $order->get_order_number(),
      'p_recipient_name' => $recipient_name,
      'p_phone'          => $phone,
      'p_address_raw'    => $address_raw,
      'p_subdistrict'    => null,
      'p_city'           => $city,
      'p_province'       => $province,
      'p_postal_code'    => $postal,
      'p_products'       => $products,
    'p_email'    => $email,
    );

    $resp = wp_remote_request( 'https://misrdmmvukdpranxnqjq.supabase.co/rest/v1/rpc/jastip_ingest_order', array(
      'method'  => 'POST',
      'headers' => array(
        'Content-Type'  => 'application/json',
        'apikey'        => '<SUPABASE_ANON_KEY>',
        'Authorization' => 'Bearer <SUPABASE_ANON_KEY>',
      ),
      'body'    => wp_json_encode( $payload ),
      'blocking' => false,
            'timeout' => 10,
    ) );

    if ( is_wp_error( $resp ) ) {
      error_log( 'Jastip ingest error for order ' . $order_id . ': ' . $resp->get_error_message() );
    }
  }
}

add_action( 'woocommerce_order_status_processing', 'jd_jastip_check_order', 20, 1 );
add_action( 'woocommerce_order_status_completed', 'jd_jastip_check_order', 20, 1 );
add_action( 'woocommerce_order_status_refunded', 'jd_jastip_check_order', 20, 1 );

// Jedda — Stop identical WooCommerce error notices from stacking up in the session queue.
// The theme's AJAX add-to-cart never flushes wc notices, so repeated blocked attempts
// (private-item cart lock, purchase limits, etc.) pile up identical messages that all
// dump out at once on the next full page render. wc_add_notice() runs this filter and
// skips adding the notice when the filter returns an empty string.

add_filter( 'woocommerce_add_error', function ( $message ) {
    if ( ! function_exists( 'wc_get_notices' ) || ! function_exists( 'WC' ) || ! WC() || ! WC()->session ) {
        return $message;
    }
    $incoming = trim( wp_strip_all_tags( (string) $message ) );
    if ( '' === $incoming ) {
        return $message;
    }
    foreach ( (array) wc_get_notices( 'error' ) as $notice ) {
        $existing = is_array( $notice ) ? ( isset( $notice['notice'] ) ? $notice['notice'] : '' ) : $notice;
        if ( trim( wp_strip_all_tags( (string) $existing ) ) === $incoming ) {
            return ''; // identical error already queued — skip the duplicate
        }
    }
    return $message;
} );

// Jedda — Jastip Order Status Sync
// Menjaga jastip_orders.order_status + order_date tetap akurat di Supabase saat
// status order berubah (processing -> completed / refunded). Sengaja dipisah dari
// Jastip Live Detector (14034) dan jalan SETELAHNYA (priority 30 > 20) supaya baris
// order barunya sudah ter-insert dulu. PATCH by order_no: kalau ordernya tidak ada
// di jastip_orders (bukan produk watched), PATCH ini tidak match apa-apa — aman.
add_action( 'woocommerce_order_status_processing', 'jd_jastip_sync_status', 30 );
add_action( 'woocommerce_order_status_completed', 'jd_jastip_sync_status', 30 );
add_action( 'woocommerce_order_status_refunded', 'jd_jastip_sync_status', 30 );

function jd_jastip_sync_status( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order ) { return; }

	$sb_url = 'https://misrdmmvukdpranxnqjq.supabase.co';
	$sb_key = '<SUPABASE_ANON_KEY>';

	$date = $order->get_date_created() ? $order->get_date_created()->date( 'c' ) : null;

	wp_remote_request(
		$sb_url . '/rest/v1/jastip_orders?order_no=eq.' . rawurlencode( $order->get_order_number() ),
		array(
			'method'   => 'PATCH',
			'headers'  => array(
				'apikey'        => $sb_key,
				'Authorization' => 'Bearer ' . $sb_key,
				'Content-Type'  => 'application/json',
				'Prefer'        => 'return=minimal',
			),
			'body'     => wp_json_encode( array(
				'order_status' => $order->get_status(),
				'order_date'   => $date,
			) ),
			'timeout'  => 3,
			'blocking' => false,
		)
	);
}

// Jedda M10 — Buy Now (theme direct-checkout, classic full-page add) goes straight to /checkout/.
// [snippet 14045, code_type: php]
// IMPORTANT: skip AJAX 'Add to Cart' (XHR) so the drawer flow stays intact — only the
// classic full-page Buy Now submit should redirect. XHR adds must return the normal URL.
add_filter( 'woocommerce_add_to_cart_redirect', function ( $url ) {
    $is_xhr = ( ! empty( $_SERVER['HTTP_X_REQUESTED_WITH'] ) && strtolower( $_SERVER['HTTP_X_REQUESTED_WITH'] ) === 'xmlhttprequest' )
           || ( function_exists( 'wp_doing_ajax' ) && wp_doing_ajax() )
           || isset( $_REQUEST['wc-ajax'] );
    if ( $is_xhr ) { return $url; }
    if ( function_exists( 'WC' ) && WC()->cart && ! WC()->cart->is_empty() && function_exists( 'wc_get_checkout_url' ) ) {
        return wc_get_checkout_url();
    }
    return $url;
}, 20 );
